patch:
diff --git a/repro-no-var-tdz.js b/repro-no-var-tdz.js
new file mode 100644
index 0000000..4d33eab
--- /dev/null
+++ b/repro-no-var-tdz.js
@@ -0,0 +1,51 @@
+"use strict";
+
+/*
+ * Reproduction: `no-var` autofix turns `var` into `let` and the fixed code
+ * throws "ReferenceError: Cannot access 'o' before initialization".
+ * Each case is linted with `no-var` + autofix, then the original and the
+ * fixed code are both executed. Exit code 1 means at least one fix broke code.
+ */
+const { Linter } = require("./lib/api");
+const vm = require("node:vm");
+
+const cases = [
+	// Exact example from the report (wrapped in a call so it can run as a script).
+	"function a() { console.log(o); var o; return o; } a();",
+
+	// Same TDZ hazard, reached through a hoisted function called from the
+	// declaration's own initializer.
+	"function a() { var o = h(); function h() { return o; } } a();",
+	"function a() { var o = 1 + h(); return o; function h() { return o; } } a();",
+	"function a() { var p = 1, o = h(); function h() { return o; } } a();",
+];
+
+function run(code) {
+	try {
+		vm.runInNewContext(code, { console: { log() {} } });
+		return "ok";
+	} catch (error) {
+		return `${error.name}: ${error.message}`;
+	}
+}
+
+const linter = new Linter();
+let broken = 0;
+
+for (const code of cases) {
+	const result = linter.verifyAndFix(code, {
+		languageOptions: { ecmaVersion: 2022, sourceType: "script" },
+		rules: { "no-var": "error" },
+	});
+	const before = run(code);
+	const after = run(result.output);
+	const isBroken = result.fixed && before === "ok" && after !== "ok";
+
+	broken += isBroken ? 1 : 0;
+	console.log(`${isBroken ? "BROKEN" : result.fixed ? "fixed, ok" : "not fixed"}`);
+	console.log(`  input:  ${code}   [runs: ${before}]`);
+	console.log(`  output: ${result.output}   [runs: ${after}]\n`);
+}
+
+console.log(`${broken} of ${cases.length} cases broken by the no-var autofix`);
+process.exitCode = broken ? 1 : 0;
